<?php
namespace App\Http\Controllers;
use App\Models\Order; use App\Models\Payment; use App\Services\BkashService; use App\Services\CartService; use App\Services\OrderService; use App\Services\SmsService; use Illuminate\Http\Request; use Throwable;
class BkashController extends Controller { public function __construct(private BkashService $bkash,private OrderService $orders,private CartService $cart,private SmsService $sms){} public function callback(Request $r){$paymentId=$r->query('paymentID');$status=$r->query('status');$order=Order::where('payment_id',$paymentId)->first();if(!$order)return redirect()->route('home')->with('error','Order not found for this payment.');$payment=Payment::firstOrCreate(['order_id'=>$order->id,'payment_id'=>$paymentId],['provider'=>'bkash','status'=>'initiated','amount'=>$order->total]);if($status!=='success'){$order->update(['payment_status'=>'failed']);$payment->update(['status'=>'failed','payload'=>$r->query()]);return redirect()->route('order.success',$order->order_number)->with('error','bKash payment was not completed.');}try{$result=$this->bkash->execute($paymentId);if(($result['transactionStatus']??'')!=='Completed'&&($result['statusCode']??'')!=='0000')throw new \RuntimeException($result['statusMessage']??'Payment could not be verified.');$order->update(['payment_status'=>'paid','transaction_id'=>$result['trxID']??null,'status'=>'confirmed']);$payment->update(['status'=>'paid','transaction_id'=>$result['trxID']??null,'payload'=>$result]);$this->orders->commitStock($order);$this->cart->clear();session()->forget('pending_order');$this->sms->send($order->phone,"Payment received for {$order->order_number}. Thank you for shopping with Aesthetic Store.");return redirect()->route('order.success',$order->order_number)->with('success','Payment successful.');}catch(Throwable $e){$order->update(['payment_status'=>'failed']);$payment->update(['status'=>'failed','payload'=>['error'=>$e->getMessage()]]);return redirect()->route('order.success',$order->order_number)->with('error',$e->getMessage());}}}
